  block.append(node('p','כפתור: '+(({SHOP_NOW:'לקנייה באתר',SIGN_UP:'להרשמה',LEARN_MORE:'למידע נוסף'})[cta]||String(cta||'לא אומת'))));
  for(const image of spec?.images||[]){const source=byKey.get(image.hash?.ref),label=(image.adlabels||[]).some(x=>x.name==='story_original')?'סטורי':'פוסט';if(source)block.append(node('small',label+': '+String(source.source_filename||source.params?.name||image.hash.ref)))}
