function calculateBusiness(){const fields=['product-sales','shipping-sales','product-cost','courier-cost','fee-rate','packaging-cost'];const values=fields.map(id=>{const raw=$('business-'+id).value;return raw.trim()===''?null:Number(raw)});if(values.some(x=>x===null||!Number.isFinite(x)||x<0)||values[4]>100){$('business-result').textContent='מלא את כל שש העלויות וההכנסות כדי לחשב. נתון חסר אינו אפס.';return}const [sales,shipping,cost,courier,fee,pack]=values;const margin=(sales+shipping)/1.18-cost-courier-(sales+shipping)*fee/100-pack;$('business-result').textContent='תרומה משוערת להזמנה לפני פרסום: '+new Intl.NumberFormat('he-IL',{style:'currency',currency:'ILS',maximumFractionDigits:2}).format(margin)+'. זו נקודת איזון חשבונית בתרחיש בלבד, לפני רווח נדרש, הוצאות קבועות וטיפול בהחזרות. '+(margin<=0?'בתרחיש הזה אין יתרה חיובית למימון פרסום.':'זה אינו יעד סקייל או אישור הוצאה.');}
$('business-calculate').onclick=calculateBusiness;

let operationTask=null,sourceSelection=new Set(),sourceSelectionKey='',sourceRevisionNotice='',sourceCopyChoices=new Map();
