async function sendSystemMessage(){
 const question=$('note').value.trim();if(question.length<3){message('כתוב מה תרצה לעשות');return}
 if(weeklyPerformanceQuestion(question)){await answerWeeklyPerformance(question);return}
 const selected=studioData?.ads?.find(a=>a.id===(claudeContextAd||studioSelected));const followup=question.match(/^(\d+(?:\.\d{1,2})?)\s*(?:₪|שקל|שקלים|שח)?$/);const plan=pendingSystemPlan&&followup?{...pendingSystemPlan,needs_amount:false,budget_minor:operationBudgetMinor(followup[1])}:systemIntentPlan(question,selected);
 if(plan.kind==='question'){await sendClaudeQuestion();return}
 if(plan.kind==='reports'){$('note').value='';sessionStorage.removeItem('rosery-unsent');show('reports');return}
 if(plan.kind==='materials'){const valid=/^https:\/\/drive\.google\.com\/(?:drive\/folders\/[A-Za-z0-9_-]{10,150}|file\/d\/[A-Za-z0-9_-]{10,150}(?:\/view|\/preview)?)\/?(?:\?(?:usp|resourcekey)=[A-Za-z0-9_-]+(?:&(?:usp|resourcekey)=[A-Za-z0-9_-]+)*)?$/;const urls=[...new Set((question.match(/https:\/\/[^\s<>]+/g)||[]).map(url=>url.replace(/[),.;]+$/,'')).filter(url=>valid.test(url)))];let brief=question;for(const url of urls)brief=brief.replaceAll(url,'');brief=brief.trim()||question;const accepted=preparationTaskUI?.prefillNew?.({brief,drive_urls:urls})===true;if(!accepted){systemReceipt('ההודעה נשארה בצ׳אט. קיימת טיוטה שלא נשלחה או שטופס ההכנה עדיין אינו זמין; לא החלפתי חומרים ולא שלחתי דבר.');return}show('operations');selectOperationTask('add');$('note').value='';sessionStorage.removeItem('rosery-unsent');return}
 if(plan.kind==='unsupported'){systemReceipt(plan.message);setStudioPane('chat');return}
 if(plan.kind==='needs_target'){systemReceipt('בחר מודעה, וציין אם השינוי מיועד למודעה, לאדסט או לקמפיין שלה. לא אבחר במקומך רמה רחבה יותר.');setStudioPane('chat');return}
 if(plan.needs_amount){pendingSystemPlan={...plan};const root=systemReceipt('איזה תקציב יומי לשמור ב־'+plan.entity_name+'? לפני ביצוע תוצג בדיקה לאישור.');const label=node('label','תקציב יומי בש״ח'),input=node('input'),button=node('button','הכן לבדיקה','primary');input.type='number';input.min='0.01';input.step='0.01';input.inputMode='decimal';input.id='system-budget-input';label.setAttribute('for',input.id);button.onclick=()=>{const minor=operationBudgetMinor(input.value);if(minor===null){input.focus();return}prepareSystemChange({...plan,budget_minor:minor,needs_amount:false})};root.append(label,input,button);setStudioPane('chat');return}
 if(operationsBusy)return;pendingSystemPlan=null;$('note').value='';sessionStorage.removeItem('rosery-unsent');await prepareSystemChange(plan);
}
