function decisionKey(item){return item.id+':'+JSON.stringify(item.next_action?.digest||item.source_binding||item.source_sha256||'')}
function deferredDecision(item){try{return localStorage.getItem('rosery-deferred:'+decisionKey(item))==='1'}catch{return false}}
function deferDecision(item,value){try{if(value)localStorage.setItem('rosery-deferred:'+decisionKey(item),'1');else localStorage.removeItem('rosery-deferred:'+decisionKey(item));renderSuggestions()}catch{alert('לא ניתן לשמור את הבחירה בדפדפן הזה. ההצעה נשארה מוצגת.')}}
function spendImpact(item){
 const before=item.before||{},after=item.after||{};
 for(const [field,label] of [['daily_budget','ליום'],['lifetime_budget','לתקופה']]){
  const b=Number(before[field]),a=Number(after[field]);
  if(before[field]!=null&&after[field]!=null&&Number.isFinite(b)&&Number.isFinite(a)&&a!==b)return 'תקציב נוכחי: '+operationMoney(b,'ILS')+' '+label+'; תקציב מוצע: '+operationMoney(a,'ILS')+' '+label+'. זהו שינוי בתקציב, לא תחזית להוצאה בפועל.';
 }
 if(after.status==='PAUSED')return 'השהיית הפריט. החיסכון בפועל תלוי בהפצה ובתקציב ההורה ואינו מחושב כאן.';
 if(after.status==='ACTIVE')return 'הפעלה עשויה לחדש הוצאה. התקציב החל יוצג בבדיקת הפעולה המדויקת.';
 return 'ההשפעה על ההוצאה טרם חושבה. יש לבדוק את התקציב המדויק לפני אישור.';
}
