  const ask=node('button','יש לי שאלה','secondary');ask.onclick=()=>{const prefix='לגבי ההצעה: '+item.title+'\nהסיבה שהוצגה: '+item.why+'\nמגבלת ההצעה: '+item.risk+'\n\nהשאלה שלי: ';if(!$('note').value.startsWith(prefix))$('note').value=prefix+$('note').value;sessionStorage.setItem('rosery-unsent',$('note').value);claudeContextAd=null;context='';show('studio');setStudioPane('chat');$('note').focus();};buttons.append(run,ask);if(!local){const defer=node('button','לא עכשיו','link-button');defer.onclick=()=>deferDecision(item,true);buttons.append(defer)}card.append(buttons,result);
  if(ownerActionReceipts.has(item.id)){renderOwnerResult(result,ownerActionReceipts.get(item.id));run.textContent='הצג את הניתוח'}
