async function runSuggestedCheck(item){
 suggestionChecks.set(item.id,'בודק את הנתונים העדכניים…');renderSuggestions();const prior=managementReport?.freshness?.meta_last_success_at;await loadReport(true);
 const fresh=managementReport?.freshness?.state==='fresh',now=managementReport?.freshness?.meta_last_success_at;
 const e=managementReport?.windows?.['3']?.adsets?.find(x=>x.id===item.entity_id);let conclusion;
 if(!fresh||now===prior)conclusion='לא אומת עדכון חדש מהמקור. הבדיקה אינה מספקת להחלטת שינוי; לא בוצע דבר בקמפיינים.';
 else if(item.target==='refresh')conclusion='התקבל עדכון חדש. ההצעות חושבו מחדש מהדוח המעודכן.';
 else if(!e)conclusion='האדסט לא נמצא בדוח המעודכן; אין בסיס לפעולת שינוי.';
 else if(managementReport?.recommendations?.recommendations?.some(d=>d.entity_type==='adset'&&d.entity_id===item.entity_id)){const decision=managementReport.recommendations.recommendations.find(d=>d.entity_type==='adset'&&d.entity_id===item.entity_id);conclusion='הנתונים רועננו. '+decision.rationale+' לא בוצע שינוי בקמפיינים.';}
 else if(typeof e.purchases!=='number')conclusion='בדקתי מחדש: פירוט הרכישות עדיין חסר. המסקנה כרגע: אין בסיס מאומת להציע עצירה או הגדלה. לא בוצע שינוי.';
 else conclusion='הבדיקה המעודכנת מציגה '+e.purchases+' רכישות מיוחסות'+(Number.isFinite(e.spend)?' והוצאה של '+reportNumber(e.spend,true):'; ההוצאה אינה ידועה')+'. '+(weeklyCost(e)!==null?'עלות לרכישה: '+reportNumber(weeklyCost(e),true)+'. ':'עלות לרכישה אינה זמינה להשוואה. ')+'טרם אומתו יעד רווחיות וזמן מאז שינוי אחרון, ולכן לא הוכנה המלצת תקציב או עצירה.';
 suggestionChecks.set(item.id,conclusion);renderSuggestions();
}
function suggestionExplanation(item,question){
 if(/למה|מדוע/.test(question))return item.why+' '+item.risk+'.';
 if(/כמה|עלות|הוצא|רכיש/.test(question))return item.evidence.join(' · ')+'. אלו תוצאות מיוחסות לתקופה, לא רווח או לקוחות חדשים מאומתים.';
 if(/לעצור|להגדיל|תקציב|סקייל/.test(question))return 'אין כרגע בהצעה יעד תקציב או עצירה מאומתים. '+item.why+' הבדיקה נועדה להכין בסיס להחלטה; היא לא אישור לשינוי.';
 return 'הצעד שהמערכת יכולה לבצע כעת הוא רענון וניתוח חוזר של האדסט. '+item.why+' לשאלה הזאת אין כאן עדיין תשובה מעבר לנתונים המוצגים; אין להסיק שנבדקה אוטומטית במקור נוסף.';
}

