// Owner-local evidence projection. Does not submit data to a model or execute ads.
let decisionMemoryLoading=false;
async function loadDecisionMemory(){
 const root=$('decision-memory-content');if(!root||decisionMemoryLoading)return;
 if(!localMode){root.textContent='זיכרון החשבון זמין בסביבת הבעלים המקומית.';return}
 decisionMemoryLoading=true;
 try{
  const value=await request('/api/decision-memory');
  root.replaceChildren();
  const stages=[
   ['מה למדנו מהעבר',value.past.status==='historical_snapshot'?value.past.rows+' מודעות בתמונת מצב מ־'+stamp(value.past.captured_at)+'; '+value.past.unknown_purchase_rows+' עם נתוני רכישה חסרים.':'עדיין אין היסטוריה מיובאת לחשבון.'],
   ['מה קורה עכשיו',value.now.status==='fresh_connected_snapshot'?'נתוני מטא מ־'+stamp(value.now.observed_at)+'; דיווח מיוחס, ללא הוכחת רווח.':'אין כרגע תמונת מצב עדכנית ומלאה שאפשר להסתמך עליה להחלטה.'],
   ['מה מומלץ ולמה','נאספות ראיות להשוואה. טרם נוצרה המלצה שנבדקה מול המודל; אין אישור לשינוי.'],
   ['מה קרה בעקבות ההחלטה',value.after.observations.length?'יש תצפית מקושרת ביומן. היא אינה מוכיחה שההחלטה בוצעה או גרמה לתוצאה.':'עדיין אין ראיות תוצאה מקושרות להחלטה ביומן הזה.']
  ];
  for(const [title,description]of stages){root.append(node('h3',title),node('p',description))}
  const examples=node('details');examples.append(node('summary','דוגמאות מהעבר — הצלחות, תוצאות חלשות וחסר'));
  for(const item of value.past.examples||[]){examples.append(node('p',item.name+' · רכישות: '+(item.purchases??'חסר')+' · הוצאה: '+(item.spend??'חסר')+' '+(value.past.currency||'')+' · ROAS: '+(item.roas==null?'חסר':item.roas.toFixed(2))))}
  root.append(examples,node('small','הראיות מוצגות מקומית. הן אינן מצורפות אוטומטית לשיחת Claude; הרשאות השיתוף ומסלול האישור לא השתנו.'));
 }catch{root.textContent='לא ניתן לאמת את זיכרון החשבון כרגע. מידע חסר אינו אפס.'}
 finally{decisionMemoryLoading=false}
}
